import{_ as e,o as a,c as d,a2 as l}from"./chunks/framework.CAlA1Nx7.js";const p=JSON.parse('{"title":"Vito API Reference 📚","description":"","frontmatter":{},"headers":[],"relativePath":"api/overview.md","filePath":"api/overview.md"}'),o={name:"api/overview.md"};function c(i,t,n,r,s,h){return a(),d("div",null,[...t[0]||(t[0]=[l('<h1 id="vito-api-reference-📚" tabindex="-1">Vito API Reference 📚 <a class="header-anchor" href="#vito-api-reference-📚" aria-label="Permalink to &quot;Vito API Reference 📚&quot;">​</a></h1><p>Tài liệu chi tiết về các hàm, đối tượng chính trong <strong>Vito Web Framework Core Engine</strong>.</p><hr><h2 id="🏗-vitoapp-class" tabindex="-1">🏗 <code>VitoApp</code> Class <a class="header-anchor" href="#🏗-vitoapp-class" aria-label="Permalink to &quot;🏗 `VitoApp` Class&quot;">​</a></h2><h3 id="createapp" tabindex="-1"><code>createApp()</code> <a class="header-anchor" href="#createapp" aria-label="Permalink to &quot;`createApp()`&quot;">​</a></h3><p>Khởi tạo một thể hiện mới của ứng dụng Vito.</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">let</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> app </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> createApp</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><h3 id="app-get-path-handler-app-post-path-handler-app-put-app-delete" tabindex="-1"><code>app.get(path, handler)</code> / <code>app.post(path, handler)</code> / <code>app.put()</code> / <code>app.delete()</code> <a class="header-anchor" href="#app-get-path-handler-app-post-path-handler-app-put-app-delete" aria-label="Permalink to &quot;`app.get(path, handler)` / `app.post(path, handler)` / `app.put()` / `app.delete()`&quot;">​</a></h3><p>Đăng ký route handler cho phương thức HTTP tương ứng.</p><h3 id="app-group-prefix-callback" tabindex="-1"><code>app.group(prefix, callback)</code> <a class="header-anchor" href="#app-group-prefix-callback" aria-label="Permalink to &quot;`app.group(prefix, callback)`&quot;">​</a></h3><p>Tạo nhóm các đường dẫn với chung tiền tố URL.</p><h3 id="app-use-middleware" tabindex="-1"><code>app.use(middleware)</code> <a class="header-anchor" href="#app-use-middleware" aria-label="Permalink to &quot;`app.use(middleware)`&quot;">​</a></h3><p>Thêm middleware vào pipeline xử lý request.</p><h3 id="app-setstrictslash-strict-boolean" tabindex="-1"><code>app.setStrictSlash(strict: boolean)</code> <a class="header-anchor" href="#app-setstrictslash-strict-boolean" aria-label="Permalink to &quot;`app.setStrictSlash(strict: boolean)`&quot;">​</a></h3><p>Bật/tắt chế độ Strict Trailing Slash Normalization (<code>/users/</code> vs <code>/users</code>). Mặc định: <code>false</code> (Lax mode).</p><h3 id="app-setnotfoundhandler-handler" tabindex="-1"><code>app.setNotFoundHandler(handler)</code> <a class="header-anchor" href="#app-setnotfoundhandler-handler" aria-label="Permalink to &quot;`app.setNotFoundHandler(handler)`&quot;">​</a></h3><p>Thiết lập handler tùy chỉnh khi không tìm thấy route (404 Not Found).</p><h3 id="app-listen-port" tabindex="-1"><code>app.listen(port)</code> <a class="header-anchor" href="#app-listen-port" aria-label="Permalink to &quot;`app.listen(port)`&quot;">​</a></h3><p>Mở socket và bắt đầu lắng nghe kết nối HTTP trên cổng được chỉ định.</p><hr><h2 id="📊-observability-metrics-dx-phase-14" tabindex="-1">📊 Observability, Metrics &amp; DX (<code>Phase 14</code>) <a class="header-anchor" href="#📊-observability-metrics-dx-phase-14" aria-label="Permalink to &quot;📊 Observability, Metrics &amp; DX (`Phase 14`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Hàm / Structure</th><th style="text-align:left;">Package</th><th style="text-align:left;">Mô Tả</th></tr></thead><tbody><tr><td style="text-align:left;"><code>createPrometheusRegistry()</code></td><td style="text-align:left;"><code>packages/metrics/metrics.vit</code></td><td style="text-align:left;">Khởi tạo Prometheus Metrics Registry thu thập chỉ số HTTP &amp; OS.</td></tr><tr><td style="text-align:left;"><code>registry.recordRequest(method, path, status, duration)</code></td><td style="text-align:left;"><code>packages/metrics/metrics.vit</code></td><td style="text-align:left;">Ghi nhận thông số HTTP Request cho các phân vị latency (p50, p90, p99).</td></tr><tr><td style="text-align:left;"><code>registry.renderPrometheusMetrics()</code></td><td style="text-align:left;"><code>packages/metrics/metrics.vit</code></td><td style="text-align:left;">Xuất chuỗi dữ liệu định dạng chuẩn Prometheus exposition format text.</td></tr><tr><td style="text-align:left;"><code>extractTraceParent(header)</code> / <code>injectTraceParent</code></td><td style="text-align:left;"><code>packages/metrics/metrics.vit</code></td><td style="text-align:left;">Trích xuất và truyền dẫn OpenTelemetry (OTel) W3C <code>traceparent</code> headers.</td></tr><tr><td style="text-align:left;"><code>createMockHttpEngine()</code></td><td style="text-align:left;"><code>packages/testing/testing.vit</code></td><td style="text-align:left;">Khởi tạo In-Memory Fast HTTP Injector cho Test Suite.</td></tr><tr><td style="text-align:left;"><code>mockEngine.inject(app, method, path, headers, body)</code></td><td style="text-align:left;"><code>packages/testing/testing.vit</code></td><td style="text-align:left;">Giả lập HTTP Request trực tiếp trên RAM không qua TCP socket.</td></tr><tr><td style="text-align:left;"><code>createTestDbFixture(name)</code></td><td style="text-align:left;"><code>packages/testing/testing.vit</code></td><td style="text-align:left;">Khởi tạo bộ nạp dữ liệu mẫu cho Test Suite.</td></tr><tr><td style="text-align:left;"><code>fixture.beginIsolationTransaction()</code> / <code>rollbackIsolationTransaction</code></td><td style="text-align:left;"><code>packages/testing/testing.vit</code></td><td style="text-align:left;">Tự động ROLLBACK CSDL sau mỗi test case để duy trì trạng thái sạch.</td></tr><tr><td style="text-align:left;"><code>createVitCodeGenerator()</code></td><td style="text-align:left;"><code>packages/cli/cli.vit</code></td><td style="text-align:left;">Sinh mã nguồn mẫu cho Controller, Service, Middleware, Model, Migration.</td></tr><tr><td style="text-align:left;"><code>createVitDoctor()</code></td><td style="text-align:left;"><code>packages/cli/cli.vit</code></td><td style="text-align:left;">Thực thi chẩn đoán môi trường phát triển và kiểm tra tài nguyên hệ thống.</td></tr></tbody></table><hr><h2 id="🔒-auth-security-suite-packages-packages-auth" tabindex="-1">🔒 Auth &amp; Security Suite Packages (<code>packages/auth/</code>) <a class="header-anchor" href="#🔒-auth-security-suite-packages-packages-auth" aria-label="Permalink to &quot;🔒 Auth &amp; Security Suite Packages (`packages/auth/`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Function / Struct</th><th style="text-align:left;">Package</th><th style="text-align:left;">Mô Tả</th></tr></thead><tbody><tr><td style="text-align:left;"><code>verifyJwtToken(token, secret, algo)</code></td><td style="text-align:left;"><code>packages/auth/jwt.vit</code></td><td style="text-align:left;">Xác thực chữ ký JWT Token (<code>HS256</code>, <code>RS256</code>, <code>ES256</code>) trong $&lt; 0.1\\text{ms}$.</td></tr><tr><td style="text-align:left;"><code>parseJwtToken(token)</code></td><td style="text-align:left;"><code>packages/auth/jwt.vit</code></td><td style="text-align:left;">Trích xuất thông tin Header và Payload Claims từ chuỗi JWT Raw.</td></tr><tr><td style="text-align:left;"><code>validateJwtClaims(jwt, now, exp, nbf)</code></td><td style="text-align:left;"><code>packages/auth/jwt.vit</code></td><td style="text-align:left;">Kiểm tra thời gian hết hạn (<code>exp</code>) và chưa hiệu lực (<code>nbf</code>).</td></tr><tr><td style="text-align:left;"><code>jwtGuardMiddleware</code></td><td style="text-align:left;"><code>packages/auth/jwt.vit</code></td><td style="text-align:left;">Middleware tự động xác thực Bearer token và từ chối HTTP 401 khi không đủ quyền.</td></tr><tr><td style="text-align:left;"><code>createGoogleOAuthProvider(...)</code></td><td style="text-align:left;"><code>packages/auth/oauth.vit</code></td><td style="text-align:left;">Khởi tạo OAuth2 &amp; OIDC Config cho Google Provider với PKCE.</td></tr><tr><td style="text-align:left;"><code>createGitHubOAuthProvider(...)</code></td><td style="text-align:left;"><code>packages/auth/oauth.vit</code></td><td style="text-align:left;">Khởi tạo OAuth2 Config cho GitHub Provider.</td></tr><tr><td style="text-align:left;"><code>createMicrosoftOAuthProvider(...)</code></td><td style="text-align:left;"><code>packages/auth/oauth.vit</code></td><td style="text-align:left;">Khởi tạo OAuth2 Config cho Microsoft Azure AD / Entra ID.</td></tr><tr><td style="text-align:left;"><code>config.generateAuthorizationUrl(state, challenge)</code></td><td style="text-align:left;"><code>packages/auth/oauth.vit</code></td><td style="text-align:left;">Sinh URL chuyển hướng đăng nhập OAuth2 tích hợp PKCE challenge.</td></tr><tr><td style="text-align:left;"><code>createApiKeyStore()</code></td><td style="text-align:left;"><code>packages/auth/apikey.vit</code></td><td style="text-align:left;">Khởi tạo Bộ lưu trữ API Key và quản lý Hạn ngạch Rate Limit từng Client Key.</td></tr><tr><td style="text-align:left;"><code>hashApiKey(rawKey)</code></td><td style="text-align:left;"><code>packages/auth/apikey.vit</code></td><td style="text-align:left;">Mã hóa 1 chiều API Key bảo mật cho việc lưu trữ CSDL.</td></tr><tr><td style="text-align:left;"><code>hashPasswordArgon2id(pass, salt, params)</code></td><td style="text-align:left;"><code>packages/auth/crypto.vit</code></td><td style="text-align:left;">Băm mật khẩu Argon2id tuân thủ khuyến nghị OWASP.</td></tr><tr><td style="text-align:left;"><code>hashPasswordBcrypt(pass, salt, cost)</code></td><td style="text-align:left;"><code>packages/auth/crypto.vit</code></td><td style="text-align:left;">Băm mật khẩu Bcrypt với cấu hình Cost Factor tùy chỉnh.</td></tr><tr><td style="text-align:left;"><code>encryptAES256GCM(plain, key, iv, ad)</code></td><td style="text-align:left;"><code>packages/auth/crypto.vit</code></td><td style="text-align:left;">Mã hóa dữ liệu hai chiều chuẩn AES-256-GCM AEAD (<code>iv:ciphertext:tag</code>).</td></tr><tr><td style="text-align:left;"><code>decryptAES256GCM(payload, key, ad)</code></td><td style="text-align:left;"><code>packages/auth/crypto.vit</code></td><td style="text-align:left;">Giải mã dữ liệu và kiểm tra tính toàn vẹn GCM Tag.</td></tr><tr><td style="text-align:left;"><code>timingSafeEqual(strA, strB)</code></td><td style="text-align:left;"><code>packages/auth/crypto.vit</code></td><td style="text-align:left;">So sánh chuỗi Constant-time phòng chống Side-channel Timing Attack.</td></tr><tr><td style="text-align:left;"><code>createRoleGuard(role, currentRoles)</code></td><td style="text-align:left;"><code>packages/auth/rbac.vit</code></td><td style="text-align:left;">Khởi tạo RBAC Guard kiểm tra vai trò người dùng (từ chối HTTP 403).</td></tr><tr><td style="text-align:left;"><code>createPermissionGuard(perm, currentPerms)</code></td><td style="text-align:left;"><code>packages/auth/rbac.vit</code></td><td style="text-align:left;">Khởi tạo RBAC Guard kiểm tra quyền hạn thao tác route.</td></tr><tr><td style="text-align:left;"><code>createGateEngine()</code></td><td style="text-align:left;"><code>packages/auth/rbac.vit</code></td><td style="text-align:left;">Khởi tạo Engine kiểm tra phân quyền ABAC theo ngữ cảnh tài nguyên.</td></tr></tbody></table><hr><h2 id="🗄️-database-orm-packages-packages-db-packages-orm" tabindex="-1">🗄️ Database &amp; ORM Packages (<code>packages/db</code> &amp; <code>packages/orm</code>) <a class="header-anchor" href="#🗄️-database-orm-packages-packages-db-packages-orm" aria-label="Permalink to &quot;🗄️ Database &amp; ORM Packages (`packages/db` &amp; `packages/orm`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Function / Struct</th><th style="text-align:left;">Package</th><th style="text-align:left;">Mô Tả</th></tr></thead><tbody><tr><td style="text-align:left;"><code>createConnectionPool(type, connStr, min, max)</code></td><td style="text-align:left;"><code>packages/db/db_pool.vit</code></td><td style="text-align:left;">Khởi tạo Connection Pool tự động mở rộng/co hẹp và khôi phục ngầm.</td></tr><tr><td style="text-align:left;"><code>pool.acquireConnection()</code></td><td style="text-align:left;"><code>packages/db/db_pool.vit</code></td><td style="text-align:left;">Mượn một kết nối CSDL hợp lệ từ Connection Pool.</td></tr><tr><td style="text-align:left;"><code>pool.checkHealthAndReconnect()</code></td><td style="text-align:left;"><code>packages/db/db_pool.vit</code></td><td style="text-align:left;">Kiểm tra sức khỏe kết nối &amp; tự động tái kết nối ngầm ($&lt; 100\\text{ms}$).</td></tr><tr><td style="text-align:left;"><code>beginTransaction(id)</code></td><td style="text-align:left;"><code>packages/orm/transaction.vit</code></td><td style="text-align:left;">Khởi tạo Giao dịch CSDL nguyên tử (Atomic Transaction) hỗ trợ ACID.</td></tr><tr><td style="text-align:left;"><code>tx.createSavepoint(name)</code></td><td style="text-align:left;"><code>packages/orm/transaction.vit</code></td><td style="text-align:left;">Tạo điểm lưu Savepoint cho giao dịch lồng nhau.</td></tr><tr><td style="text-align:left;"><code>tx.rollbackToSavepoint(name)</code></td><td style="text-align:left;"><code>packages/orm/transaction.vit</code></td><td style="text-align:left;">Khôi phục trạng thái giao dịch về Savepoint được chỉ định.</td></tr><tr><td style="text-align:left;"><code>createMigrationRunner()</code></td><td style="text-align:left;"><code>packages/orm/migration.vit</code></td><td style="text-align:left;">Tạo đối tượng quản lý và chạy Migration (Up/Down) lưu vào <code>schema_migrations</code>.</td></tr><tr><td style="text-align:left;"><code>createSchemaDiffGenerator()</code></td><td style="text-align:left;"><code>packages/orm/migration.vit</code></td><td style="text-align:left;">Sinh câu lệnh SQL Migration tự động từ định nghĩa Model Vito ORM.</td></tr><tr><td style="text-align:left;"><code>createDatabaseSeeder()</code></td><td style="text-align:left;"><code>packages/orm/migration.vit</code></td><td style="text-align:left;">Tạo bộ nạp dữ liệu mẫu (Database Seeder) cho môi trường Dev &amp; Staging.</td></tr></tbody></table><hr><h2 id="⚡-performance-packages-packages-pool-packages-router" tabindex="-1">⚡ Performance Packages (<code>packages/pool</code> &amp; <code>packages/router</code>) <a class="header-anchor" href="#⚡-performance-packages-packages-pool-packages-router" aria-label="Permalink to &quot;⚡ Performance Packages (`packages/pool` &amp; `packages/router`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Function / Helper</th><th style="text-align:left;">Package</th><th style="text-align:left;">Mô Tả</th></tr></thead><tbody><tr><td style="text-align:left;"><code>createMemoryArena()</code></td><td style="text-align:left;"><code>packages/pool/pool.vit</code></td><td style="text-align:left;">Tạo đối tượng quản lý Request Memory Arena slots tái sử dụng.</td></tr><tr><td style="text-align:left;"><code>createTcpBufferPool()</code></td><td style="text-align:left;"><code>packages/pool/pool.vit</code></td><td style="text-align:left;">Tạo Buffer Recycling Pool cho TCP Read/Write buffers.</td></tr><tr><td style="text-align:left;"><code>zeroAllocHeaderLookup(raw, target)</code></td><td style="text-align:left;"><code>packages/pool/pool.vit</code></td><td style="text-align:left;">Trích xuất giá trị Header trực tiếp từ raw HTTP stream không cấp phát memory.</td></tr><tr><td style="text-align:left;"><code>createRadixRouter(strict)</code></td><td style="text-align:left;"><code>packages/router/router.vit</code></td><td style="text-align:left;">Khởi tạo Static Route Fast Path Router với $O(1)$ memory slot lookup.</td></tr><tr><td style="text-align:left;"><code>normalizePath(path, strict)</code></td><td style="text-align:left;"><code>packages/router/router.vit</code></td><td style="text-align:left;">Chuẩn hóa đường dẫn URL theo chế độ Lax / Strict slash.</td></tr></tbody></table><hr><h2 id="📥-request-class" tabindex="-1">📥 <code>Request</code> Class <a class="header-anchor" href="#📥-request-class" aria-label="Permalink to &quot;📥 `Request` Class&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Phương Thức</th><th style="text-align:left;">Mô Tả</th><th style="text-align:left;">Ví Dụ</th></tr></thead><tbody><tr><td style="text-align:left;"><code>req.param(key)</code></td><td style="text-align:left;">Lấy giá trị tham số dynamic path <code>:key</code> hoặc <code>*wildcard</code></td><td style="text-align:left;"><code>req.param(&quot;id&quot;)</code></td></tr><tr><td style="text-align:left;"><code>req.query(key)</code></td><td style="text-align:left;">Lấy giá trị search query string <code>?key=val</code></td><td style="text-align:left;"><code>req.query(&quot;page&quot;)</code></td></tr><tr><td style="text-align:left;"><code>req.header(key)</code></td><td style="text-align:left;">Lấy giá trị HTTP request header</td><td style="text-align:left;"><code>req.header(&quot;Authorization&quot;)</code></td></tr><tr><td style="text-align:left;"><code>req.method</code></td><td style="text-align:left;">Thuộc tính trả về phương thức HTTP (GET, POST...)</td><td style="text-align:left;"><code>req.method</code></td></tr><tr><td style="text-align:left;"><code>req.path</code></td><td style="text-align:left;">Thuộc tính trả về đường dẫn URL</td><td style="text-align:left;"><code>req.path</code></td></tr></tbody></table><hr><h2 id="📤-response-class" tabindex="-1">📤 <code>Response</code> Class <a class="header-anchor" href="#📤-response-class" aria-label="Permalink to &quot;📤 `Response` Class&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Phương Thức</th><th style="text-align:left;">Mô Tả</th><th style="text-align:left;">Ví Dụ</th></tr></thead><tbody><tr><td style="text-align:left;"><code>res.setStatus(code)</code></td><td style="text-align:left;">Thiết lập HTTP Status Code (200, 404, 500...)</td><td style="text-align:left;"><code>res.setStatus(200)</code></td></tr><tr><td style="text-align:left;"><code>res.setHeader(name, val)</code></td><td style="text-align:left;">Thiết lập HTTP Response Header</td><td style="text-align:left;"><code>res.setHeader(&quot;X-Powered-By&quot;, &quot;Vito&quot;)</code></td></tr><tr><td style="text-align:left;"><code>res.setCookie(key, val, opts)</code></td><td style="text-align:left;">Ghi Cookie với chữ ký mã hóa HMAC &amp; cờ HttpOnly/SameSite</td><td style="text-align:left;"><code>res.setCookie(&quot;sid&quot;, &quot;abc&quot;, opts)</code></td></tr><tr><td style="text-align:left;"><code>res.json(jsonStr)</code></td><td style="text-align:left;">Trả về chuỗi JSON với header <code>Content-Type: application/json</code></td><td style="text-align:left;"><code>res.json(&quot;{\\&quot;ok\\&quot;:true}&quot;)</code></td></tr><tr><td style="text-align:left;"><code>res.html(htmlStr)</code></td><td style="text-align:left;">Trả về nội dung HTML với <code>Content-Type: text/html</code></td><td style="text-align:left;"><code>res.html(&quot;&lt;h1&gt;Hi&lt;/h1&gt;&quot;)</code></td></tr><tr><td style="text-align:left;"><code>res.send(textStr)</code></td><td style="text-align:left;">Trả về chuỗi Plain Text</td><td style="text-align:left;"><code>res.send(&quot;Hello World&quot;)</code></td></tr><tr><td style="text-align:left;"><code>res.sendChunk(chunk)</code></td><td style="text-align:left;">Trả về dữ liệu kiểu Stream / Chunked response</td><td style="text-align:left;"><code>res.sendChunk(data)</code></td></tr></tbody></table><hr><h2 id="⚡-websockets-event-bus-job-queue-phase-13" tabindex="-1">⚡ WebSockets, Event Bus &amp; Job Queue (<code>Phase 13</code>) <a class="header-anchor" href="#⚡-websockets-event-bus-job-queue-phase-13" aria-label="Permalink to &quot;⚡ WebSockets, Event Bus &amp; Job Queue (`Phase 13`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Hàm / Structure</th><th style="text-align:left;">Package</th><th style="text-align:left;">Mô Tả</th></tr></thead><tbody><tr><td style="text-align:left;"><code>createWebSocketServer(port, maxConn)</code></td><td style="text-align:left;"><code>packages/websocket/websocket.vit</code></td><td style="text-align:left;">Khởi tạo High-Concurrency WebSocket Server engine.</td></tr><tr><td style="text-align:left;"><code>wsServer.broadcastToRoom(room, msg)</code></td><td style="text-align:left;"><code>packages/websocket/websocket.vit</code></td><td style="text-align:left;">Gửi tin nhắn Broadcast đến toàn bộ kết nối trong một Room.</td></tr><tr><td style="text-align:left;"><code>wsServer.unicast(client, msg)</code></td><td style="text-align:left;"><code>packages/websocket/websocket.vit</code></td><td style="text-align:left;">Gửi tin nhắn đơn tới một WebSocket Client cụ thể.</td></tr><tr><td style="text-align:left;"><code>wsServer.checkHeartbeats(client, time)</code></td><td style="text-align:left;"><code>packages/websocket/websocket.vit</code></td><td style="text-align:left;">Kiểm tra Ping/Pong và giải phóng kết nối chết (Stale eviction).</td></tr><tr><td style="text-align:left;"><code>compressFrame(payload)</code> / <code>decompressFrame</code></td><td style="text-align:left;"><code>packages/websocket/websocket.vit</code></td><td style="text-align:left;">Nén và giải nén dữ liệu khung truyền WebSocket per-message deflate.</td></tr><tr><td style="text-align:left;"><code>createEventBus()</code></td><td style="text-align:left;"><code>packages/events/event_bus.vit</code></td><td style="text-align:left;">Khởi tạo Async Internal Event Bus dispatcher.</td></tr><tr><td style="text-align:left;"><code>eventBus.emitAsync(event, payload)</code></td><td style="text-align:left;"><code>packages/events/event_bus.vit</code></td><td style="text-align:left;">Phát hành sự kiện bất đồng bộ không ngắt luồng chính.</td></tr><tr><td style="text-align:left;"><code>createRedisPubSubAdapter(host, port)</code></td><td style="text-align:left;"><code>packages/events/redis_pubsub.vit</code></td><td style="text-align:left;">Tạo Redis Pub/Sub adapter giao tiếp liên Node trong cụm Server.</td></tr><tr><td style="text-align:left;"><code>createJobQueue(driver)</code></td><td style="text-align:left;"><code>packages/queue/queue.vit</code></td><td style="text-align:left;">Khởi tạo Background Job Queue (Driver: <code>&quot;memory&quot;</code> hoặc <code>&quot;redis&quot;</code>).</td></tr><tr><td style="text-align:left;"><code>jobQueue.scheduleJob(job, delayMs)</code></td><td style="text-align:left;"><code>packages/queue/queue.vit</code></td><td style="text-align:left;">Đẩy job vào hàng chờ hoãn thi hành theo thời gian thiết lập.</td></tr><tr><td style="text-align:left;"><code>jobQueue.processNextJob(shouldFail, reason)</code></td><td style="text-align:left;"><code>packages/queue/queue.vit</code></td><td style="text-align:left;">Xử lý job tiếp theo, hỗ trợ Exponential Backoff Retry &amp; DLQ.</td></tr></tbody></table>',40)])])}const y=e(o,[["render",c]]);export{p as __pageData,y as default};
